private func metricItems(days: [HealthMdCompactContextDay], selection: HealthMdMetricSelection)
  -> [HealthMdQueryItem]
{
  let selected = selectedMetricIDs(selection, in: days)
  let evidence = evidenceIndex(days)
  var seen = Set<String>()
  var points: [HealthMdMetricPoint] = []
  for day in days {
    for metric in day.metrics where selected.contains(metric.metricID) {
      let identity = "\(day.ownerDate)|\(metric.observationID)"
      guard seen.insert(identity).inserted else { continue }
      let preferredEvidence = HealthMdMetricEvidenceSelector.preferred(
        metric.evidenceIDs.compactMap { evidence[$0] }
      )
      points.append(
        HealthMdMetricPoint(
          metricID: metric.metricID,
          displayName: metric.displayName,
          ownerDate: day.ownerDate,
          value: metric.value,
          status: metric.value == nil && metric.status == .available
            ? .completeEmpty : metric.status,
          evidence: preferredEvidence.map(\.reference),
          limitations: metric.limitations
        ))
    }
  }
  return points.sorted {
    if $0.ownerDate != $1.ownerDate { return $0.ownerDate < $1.ownerDate }
    if $0.metricID != $1.metricID { return $0.metricID < $1.metricID }
    return $0.displayName < $1.displayName
  }.map(HealthMdQueryItem.metric)
}

